abel><input type="text" name="material_type" id="lessonMaterialType" placeholder="Contoh: video_dyntube" class="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" required></div><div><label for="lessonDuration" class="mb-1.5 block text-sm font-semibold text-slate-700">Durasi (detik)</label><input type="number" name="duration" id="lessonDuration" min="0" class="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" required></div></div><div><label for="lessonUrl" class="mb-1.5 block text-sm font-semibold text-slate-700">URL materi</label><textarea name="material_url" id="lessonUrl" rows="3" class="w-full rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm outline-none focus:border-indigo-500 focus:ring-4 focus:ring-indigo-100" required></textarea></div><div class="flex flex-col-reverse gap-2 border-t border-slate-100 pt-4 sm:flex-row sm:justify-end"><button type="button" onclick="closeLessonModal()" class="rounded-xl border border-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-600 hover:bg-slate-50">Batal</button><button type="submit" class="rounded-xl bg-indigo-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700"><i class="fas fa-save mr-1"></i> Simpan</button></div></form></div></div>

    <script>
        const materialModal = document.getElementById('materialModal');
        const materialVideo = document.getElementById('materialVideo');
        const materialFrame = document.getElementById('materialFrame');
        const lessonModal = document.getElementById('lessonModal');
        const lessonForm = document.getElementById('lessonForm');
        function openAddLessonModal() { document.getElementById('lessonModalTitle').textContent = 'Tambah Lesson'; lessonForm.reset(); lessonForm.action = @js(route('lessons.store')); document.getElementById('lessonFormMethod').value = 'POST'; lessonModal.classList.remove('hidden'); lessonModal.classList.add('flex'); document.getElementById('lessonTitle').focus(); }
        function openEditLesson(item) { document.getElementById('lessonModalTitle').textContent = 'Edit Lesson'; lessonForm.action = `/lessons/${item.id}`; document.getElementById('lessonFormMethod').value = 'PUT'; document.getElementById('lessonTitle').value = item.title ?? ''; document.getElementById('lessonTopic').value = item.topic_id ?? ''; document.getElementById('lessonMaterialType').value = item.material_type ?? ''; document.getElementById('lessonDuration').value = item.duration ?? 0; document.getElementById('lessonUrl').value = item.material_url ?? ''; lessonModal.classList.remove('hidden'); lessonModal.classList.add('flex'); document.getElementById('lessonTitle').focus(); }
        function closeLessonModal() { lessonModal.classList.add('hidden'); lessonModal.classList.remove('flex'); }
        function openMaterialModal(button) { const url = button.dataset.materialUrl; const type = button.dataset.materialType || 'Materi'; document.getElementById('materialModalTitle').textContent = button.dataset.materialTitle || 'Lesson'; document.getElementById('materialModalType').textContent = type.replaceAll('_', ' '); document.getElementById('materialExternalLink').href = url; const directVideo = /\.(mp4|webm|ogg)(\?.*)?$/i.test(url); materialVideo.classList.toggle('hidden', !directVideo); materialFrame.classList.toggle('hidden', directVideo); if (directVideo) { materialVideo.src = url; materialVideo.load(); } else { materialFrame.src = url; } materialModal.classList.remove('hidden'); materialModal.classList.add('flex'); }
        function closeMaterialModal() { materialVideo.pause(); materialVideo.removeAttribute('src'); materialVideo.load(); materialFrame.src = 'about:blank'; materialModal.classList.add('hidden'); materialModal.classList.remove('flex'); }
        document.querySelectorAll('.open-material').forEach((button) => button.addEventListener('click', () => openMaterialModal(button)));
        document.querySelectorAll('.edit-lesson').forEach((button) => button.addEventListener('click', () => openEditLesson(JSON.parse(button.dataset.lesson))));
        document.querySelectorAll('.delete-lesson').forEach((button) => button.addEventListener('click', () => { Swal.fire({ title: 'Hapus lesson?', text: 'Data materi yang dihapus tidak dapat dikembalikan.', icon: 'warning', showCancelButton: true, confirmButtonColor: '#dc2626', cancelButtonText: 'Batal', confirmButtonText: 'Ya, hapus' }).then((result) => { if (!result.isConfirmed) return; const form = document.createElement('form'); form.method = 'POST'; form.action = `/lessons/${button.dataset.deleteId}`; form.innerHTML = `@csrf<input type="hidden" name="_method" value="DELETE">`; document.body.appendChild(form); form.submit(); }); }));
        lessonModal.addEventListener('click', (event) => { if (event.target === lessonModal) closeLessonModal(); });
        materialModal.addEventListener('click', (event) => { if (event.target === materialModal) closeMaterialModal(); });
        document.addEventListener('keydown', (event) => { if (event.key === 'Escape') { closeLessonModal(); closeMaterialModal(); } });
    </script>
@endsection
